esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that migrateTo can only succeed when invoked by the original creator of C,
    // and when it succeeds it sets address(c).balance == 0 (transferred away).
    // Since this test contract is NOT the creator of c (the checker deploys a fresh c and
    // then deploys this test passing that c), we assert that migrateTo must revert for any call
    // from this contract. If the creator were this contract, then migrateTo might succeed and
    // set address(c).balance to zero; but in the checker setup the creator is different.
    // To be general for any input, we allow the input "byCreator" flag: if true we try to
    // simulate the creator calling migrateTo by first calling no-op (can't become creator),
    // so we conservatively assert: either migrateTo reverts, or it succeeds and address(c).balance == 0.

    function run(address to, bool expectRevert) public payable {
        require(to != address(0));

        // Record contract balance before the call
        uint256 beforeC = address(c).balance;

        // Attempt migrateTo(to) and observe whether it reverts.
        bool didRevert;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint256 afterC = address(c).balance;

        // General rule: migrateTo either reverts, or it succeeds and leaves c's balance as zero
        // (i.e., full transfer). We avoid arithmetic that can underflow: just compare afterC == 0.
        // We relate the observed revert to the caller's expectation flag: if caller set expectRevert==true
        // then we require that it indeed reverted; otherwise we don't force it, but still require the fundamental property.
        assert((didRevert) || (!didRevert && afterC == 0));
    }

    receive() external payable {}
}

